import json

urgency_script = '''const keywords = ["urgent", "asap", "immediately", "critical", "emergency", "down", "escalate"];
const subject = ($vars.newInboxEmail1.output.subject || "").toLowerCase();
const bodyContent = (($vars.newInboxEmail1.output.body || {}).content || "").toLowerCase();
const haystack = subject + " " + bodyContent;
const matchedKeywords = keywords.filter(k => haystack.includes(k));
return { isUrgent: matchedKeywords.length > 0, matchedKeywords: matchedKeywords };'''

vip_script = '''const vipDomains = ["acme.com", "globex-corp.com", "initech.com", "umbrella-corp.com"];
const fromAddress = (($vars.newInboxEmail1.output.from || {}).emailAddress || {}).address || "";
const email = fromAddress.toLowerCase();
const atIndex = email.indexOf("@");
const domain = atIndex >= 0 ? email.slice(atIndex + 1) : "";
return { isVip: vipDomains.includes(domain), domain: domain };'''

ticket_script = '''const instanceId = ($metadata.instanceId || "").replace(/-/g, "");
const ticketId = "TCK-" + instanceId.slice(0, 8).toUpperCase();
const subject = $vars.newInboxEmail1.output.subject || "(no subject)";
const fromAddress = (($vars.newInboxEmail1.output.from || {}).emailAddress || {}).address || "unknown sender";
const isUrgent = $vars.classifyUrgency1.output.isUrgent;
const priority = isUrgent ? "High" : "Normal";
const summary = "Support request from " + fromAddress + ": " + subject;
const createdAt = $vars.newInboxEmail1.output.receivedDateTime || "";
return { ticketId: ticketId, summary: summary, priority: priority, createdAt: createdAt };'''

with open('/tmp/urgency_inputs.json', 'w') as f:
    json.dump({"script": urgency_script}, f)
with open('/tmp/vip_inputs.json', 'w') as f:
    json.dump({"script": vip_script}, f)
with open('/tmp/ticket_inputs.json', 'w') as f:
    json.dump({"script": ticket_script}, f)
with open('/tmp/decision_inputs.json', 'w') as f:
    json.dump({"expression": "$vars.classifyUrgency1.output.isUrgent && $vars.classifyVip1.output.isVip"}, f)

print("done")
PYEOF
